'use strict';
/* Regional presentation only. Choices are quoted and committed by the coast engine. */
const coastUI={region:'city'};
const coastRegions=()=>Array.isArray(G.PLACE_REGIONS)?G.PLACE_REGIONS:[];
const coastPlaces=()=>Array.isArray(G.PLACES)?G.PLACES:[];
const coastInfo=id=>typeof G.coastInfo==='function'?G.coastInfo(s,id):null;
const coastList=()=>typeof G.coastList==='function'?G.coastList(s):[];
const coastRegionLine=id=>['city','industry'].includes(id)?'heritage':'islands';
const coastRegion=id=>coastRegions().find(r=>r.id===id)||coastRegions()[0];
const coastImage=r=>`<img src="${exText(r.image)}" alt="${exText(r.alt)}" loading="lazy" decoding="async">`;
function coastEffects(effects){const labels={crew:'folk',trained:'trente',rep:'respekt',influence:'innflytelse',loyalty:'lojalitet',fatigue:'slitasje',trust:'tillit'};return Object.entries(effects||{}).filter(([key,n])=>Number(n)!==0).map(([key,n])=>(n>0?'+':'')+exText(n)+' '+exText(labels[key]||key)).join(' · ');}
function coastFilters(){return `<div class="coast-filters" role="group" aria-label="Velg del av Stavangerregionen">${coastRegions().map(r=>`<button data-coast-region="${exText(r.id)}" aria-pressed="${coastUI.region===r.id}" class="${coastUI.region===r.id?'selected':''}"><span>${exText(r.short)}</span><small>${coastPlaces().filter(p=>p.region===r.id).length} steder</small></button>`).join('')}</div>`;}
function coastStoryStatus(q){if(s.ended)return 'HISTORIEN ER AVSLUTTET';if(q.status==='done')return 'DET DERE FIKK TIL';return `SAMTALE ${Math.min(q.total,q.step+1)} AV ${q.total}`;}
function coastStoryCard(q,compact=false){if(!q)return '<article class="coast-story-card"><h3>Det finnes en vei videre.</h3><p>Gå tilbake til kaien, eller velg et sted i byen.</p></article>';const current=q.current,place=coastPlaces().find(p=>p.id===current?.placeId),readable=q.status==='done'||s.ended;return `<article class="coast-story-card ${compact?'compact':''}"><span class="section-kicker">${exText(coastStoryStatus(q))}</span><h${compact?'3':'2'}>${exText(current?.title||q.title)}</h${compact?'3':'2'}><p>${exText(readable?q.intro:current?.text||q.intro)}</p>${current&&!readable?`<div class="coast-next-place"><span>NESTE MØTE</span><b>${exText(current.place||place?.name||'Langs kysten')}</b><small>${exText(exContactName(current.speaker))} · ${exText(current.objective||'En samtale og et valg.')}</small></div>`:''}<div class="coast-story-meta"><span>${exText(q.title)}</span><span>${Math.min(q.total,q.step)} av ${q.total} møter fullført</span></div>${q.reason&&!q.ready&&!readable?`<p class="coast-gate">${exText(q.reason)}</p>`:''}<button class="button ${compact?'ghost':'brass'}" data-coast-story="${exText(q.id)}" ${!readable&&!q.ready?'disabled':''}>${readable?'Les minnene':'Åpne samtalen'} →</button></article>`;}
function coastRegionHero(r){return `<section class="coast-region-hero">${coastImage(r)}<div><span class="section-kicker">STAVANGERREGIONEN / ${exText(r.name)}</span><h2>${exText(r.title)}</h2><p>${exText(r.text)}</p><span class="coast-route">${exText(r.route)}</span></div></section>`;}
function coastPlaceTile(p,index){const quotes=p.hooks.map(h=>exPlaceQuote(h)),open=quotes.some(q=>!q.reason),next=quotes.findIndex(q=>!q.reason),current=coastList().find(q=>q.current?.placeId===p.id),region=coastRegion(p.region);return `<article class="coast-place-tile ${current?'has-scene':''}"><div class="coast-place-heading"><span aria-hidden="true">${exText(p.symbol||'◇')}</span><span class="section-kicker">${exText(p.district)}</span>${current?'<b>MØTE PÅ LINJA</b>':''}</div><h3>${exText(p.name)}</h3><p>${exText(p.text)}</p>${p.landmarks?.length?`<div class="coast-landmarks">${p.landmarks.map(l=>`<span>${exText(l)}</span>`).join('')}</div>`:''}<div class="coast-place-hook">${exText(open?p.hooks[next].label:quotes[0]?.reason||'Historien er avsluttet.')}</div><button class="button ghost" data-ex-place="${exText(p.id)}" ${open?'':'disabled'}>${open?'Se stedet og velg':'Ingen nye valg her'} →</button></article>`;}
function coastPlacePanel(){const r=coastRegion(coastUI.region);if(!r)return '';const places=coastPlaces().filter(p=>p.region===r.id),current=coastList().filter(q=>q.current).map(q=>q.current.placeId),sorted=places.slice().sort((a,b)=>Number(current.includes(b.id))-Number(current.includes(a.id))),featured=sorted.slice(0,3),rest=sorted.slice(3);return `<section class="coast-explorer"><div class="coast-explorer-title"><span class="section-kicker">${coastPlaces().length} STEDER / FIRE RETNINGER</span><h2>Stavanger stopper ikkje ved kaien.</h2><p>Velg en del av byen. Se hvem som venter, eller følg forbindelsene videre ut mot fjorden.</p></div>${coastFilters()}${coastRegionHero(r)}<div class="coast-region-story">${coastStoryCard(coastInfo(coastRegionLine(r.id)),true)}<div class="coast-region-note"><span class="section-kicker">HERFRA KAN DU GÅ VIDERE</span><h3>${exText(r.route)}</h3><p>Et sted åpner valgene som finnes der. Den neste samtalen viser hvor møtet faktisk finner sted.</p><button class="text-button" data-view="coast">Se begge historiene langs kysten →</button></div></div><div class="coast-place-grid">${featured.map(coastPlaceTile).join('')}</div>${rest.length?`<details class="coast-directory"><summary>Flere steder i ${exText(r.name.toLowerCase())} · ${rest.length}</summary><div class="coast-place-grid">${rest.map(coastPlaceTile).join('')}</div></details>`:''}</section>`;}
function coastPolicyPanel(){if(s.ended||!s.coast)return '';const labels={personal:'Jeg følger møtene selv',community:'La fellesskapet følge opp',enterprise:'La bedriften følge opp'};return `<details class="coast-policy"><summary>Hvem følger opp mellom møtene?</summary><p>Du tar de store valgene. Se forutsetningene før du gir andre et mandat.</p><div>${Object.entries(labels).map(([id,label])=>{const q=typeof G.coastPolicyQuote==='function'?G.coastPolicyQuote(s,id):null;return `<article><button class="button ghost" data-coast-policy="${id}" aria-pressed="${s.coast.policy===id}" ${q&&(q.valid===false||q.allowed===false)?'disabled':''}>${exText(q?.label||label)}${s.coast.policy===id?' ✓':''}</button>${q?.reason?`<small>${exText(q.reason)}</small>`:''}${q?.text?`<small>${exText(q.text)}</small>`:''}</article>`;}).join('')}</div></details>`;}
function coastHistory(){return `<details class="coast-policy coast-history"><summary>Byens spor: menneskene, kunsten og arbeidet</summary><div class="coast-story-pair">${(G.CITY_HISTORY||[]).map(h=>`<article class="coast-story-card"><h3>${exText(h.title)}</h3><p>${exText(h.text)}</p><a href="${exText(h.source)}" target="_blank" rel="noopener">Les historien ved kilden ↗</a>${h.extraSource?` · <a href="${exText(h.extraSource)}" target="_blank" rel="noopener">Another Place ↗</a>`:''}</article>`).join('')}</div></details>`;}
function coastView(){return `<section class="coast-view"><div class="page-title"><div><span class="section-kicker">FJORDEN / ARBEIDET / MENNESKENE</span><h1>DET FINNES MER<br>UTENFOR KAIEN.</h1><p>Verkstedene. Øyene. Rommene vi arver. To historier om hva du gir plass til.</p></div><button class="button ghost" data-coast-places>Utforsk ${coastPlaces().length} steder →</button></div><div class="coast-story-pair">${coastList().map(q=>{const r=coastRegion(q.id==='islands'?'islands':'city');return `<section><div class="coast-story-image">${r?coastImage(r):''}<span class="section-kicker">${q.id==='islands'?'BÅTEN OG ØYENE':'ARBEIDET OG KULTURSPOR'}</span></div>${coastStoryCard(q)}</section>`;}).join('')}</div>${coastPolicyPanel()}${coastHistory()}<section class="coast-directions"><span class="section-kicker">VELG EN RETNING</span><h2>La geografien føre historien videre.</h2><div>${coastRegions().map(r=>`<button data-coast-region="${exText(r.id)}" data-coast-open-places>${coastImage(r)}<span><b>${exText(r.name)}</b><small>${exText(r.route)}</small></span><strong aria-hidden="true">↗</strong></button>`).join('')}</div></section></section>`;}
function coastOpenStory(id){const q=coastInfo(id);if(!q)return;const c=q.current,archived=s.ended||q.status==='done';if(archived){modal(`<span class="section-kicker">DET DERE HUSKER</span><h2>${exText(q.title)}</h2><p>${exText(q.intro)}</p><div class="ex-history">${(q.history||[]).map(h=>`<p>✓ ${exText(h.title||h.label||h.choice)}<small>${exText(h.label||'')} · dag ${exText(h.day)}${h.automatic?' · fulgt opp av andre':''}</small>${h.text?`<span class="coast-history-result">${exText(h.text)}</span>`:''}</p>`).join('')||'<p>Ingen møter er nedtegnet i denne runden.</p>'}</div>`);return;}if(!c)return;const p=coastPlaces().find(p=>p.id===c.placeId);modal(`<div class="coast-dialog"><span class="section-kicker">${exText(c.place||p?.name||'LANGS KYSTEN')} / ${exText(exContactName(c.speaker))}</span><h2>${exText(c.title)}</h2><p>${exText(c.text)}</p>${c.objective?`<div class="ex-objective">${exText(c.objective)}</div>`:''}<span class="coast-dialog-step">Møte ${q.step+1} av ${q.total} · ${exText(q.title)}</span><div class="ex-dialog-choices">${(c.choices||[]).map((choice,i)=>`<button class="choice" data-coast-choice="${exText(q.id)}" data-coast-step="${q.step}" data-coast-choice-id="${exText(choice.id)}" ${!q.ready||choice.allowed===false||choice.valid===false?'disabled':''}>${exText(choice.label)}<small>${choice.includedInWeek?'Inngår i arbeidsuka':exDays(choice.days||0)} · ${kr(choice.cost||0)} innsats${choice.cash?' · '+kr(choice.cash)+' i oppgjør':''}</small>${coastEffects(choice.effects)?`<small>${coastEffects(choice.effects)}</small>`:''}${choice.reason?`<small>${exText(choice.reason)}</small>`:''}</button>`).join('')}</div>${p?.fact?`<details class="coast-fact"><summary>Stedets historie</summary><p>${exText(p.fact)}</p>${p.source?`<a href="${exText(p.source)}" target="_blank" rel="noopener">Les om stedet ↗</a>`:''}</details>`:''}</div>`);}
const coastPriorPlaceQuote=exPlaceQuote;
exPlaceQuote=function(h){if(h.kind!=='coast')return coastPriorPlaceQuote(h);const q=coastInfo(h.id);return {reason:s.ended?'Runden er avsluttet.':!q?'Historien åpner snart.':q.status==='done'?null:!q.ready?q.reason:null,detail:q?.status==='done'?'Les minnene fra denne historien.':q?.current?(q.current.place||'Neste møte')+' · '+(q.current.title||q.title):q?.intro||'En samtale langs kysten.'};};
const coastPriorDoPlace=exDoPlace;
exDoPlace=function(id,index){const p=coastPlaces().find(p=>p.id===id),h=p?.hooks[index];if(h?.kind==='coast'){if(exPlaceQuote(h).reason)return;$('#dialog').close();coastOpenStory(h.id);return;}return coastPriorDoPlace(id,index);};
exPlacePanel=coastPlacePanel;
if(!nav.some(n=>n[0]==='coast'))nav.splice(2,0,['coast','03','Kysten']);nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const coastPriorRender=render;
render=function(){const current=view;if(current==='coast')view='experience';coastPriorRender();view=current;if(current==='coast'){$('#screen').innerHTML=coastView();$('#nav').querySelectorAll('[data-view]').forEach(n=>{const active=n.dataset.view==='coast';n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});}const coastTab=$('#nav [data-view="coast"]');if(coastTab)coastTab.hidden=false;if(current==='home'&&!s.ended){const invite=$('.ex-city-invite');if(invite){invite.classList.add('coast-home-invite');invite.innerHTML=`<div><span class="section-kicker">${coastPlaces().length} STEDER / FIRE RETNINGER</span><h2>Byen fortsetter over brua.</h2><p>Verftet, øyene og kultursporene. Se hvem som venter utenfor sentrum.</p></div><button class="button ghost" data-view="coast">Følg kysthistoriene →</button>`;}}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-coast-region')){coastUI.region=b.dataset.coastRegion;if(b.hasAttribute('data-coast-open-places')){exUI.section='places';view='experience';}render();}if(b.hasAttribute('data-coast-places')){exUI.section='places';view='experience';render();window.scrollTo({top:0,behavior:'auto'});}if(b.hasAttribute('data-coast-story'))coastOpenStory(b.dataset.coastStory);if(b.hasAttribute('data-coast-choice')&&!s.ended){const arg={line:b.dataset.coastChoice,choice:b.dataset.coastChoiceId,step:+b.dataset.coastStep},q=typeof G.coastQuote==='function'?G.coastQuote(s,arg):null;if(q&&(q.allowed===false||q.valid===false)){toast(q.reason||'Dette valget er ikke tilgjengelig.');return;}act('coastChoice',arg);$('#dialog').close();}if(b.hasAttribute('data-coast-policy')&&!s.ended)act('coastPolicy',b.dataset.coastPolicy);});
render();
